#!/usr/bin/env bash
# Bundle item 205_transport_isantransit_members (thread "Site: Add Transport and Foreign Affairs committees", 23 Nov 2569; asked by
# "Site: Update automatically three times a day"). One self-contained file: the payload is embedded below as base64 tar.gz
# (sha256 69995b28ef0fc256fe207b99a36728efe1980c8a37e82bcd8d1e89b7daa2cdc0).
# Member lists fetched today (23 Nov 2569 ~12:13 UTC) from the senate.go.th committee and subcommittee pages (fetch_members.js)
# and checked with members.py against the published list (13 Nov): the committee, Andaman port and ride-hailing lists are
# unchanged; the Isan transit subcommittee (scid 85211) now lists 16 people, 8 of them senators (was 13 and 5). Added, with titles,
# names and positions exactly as the Senate lists them (from 11 Nov 2569 on the Senate page):
#   นางณัฏฐินีภรณ์ จันทรโณทัย (อนุกรรมาธิการ), นางนงลักษณ์ ก้านเขียว (อนุกรรมาธิการ), นางสาวนิชาภา สุวรรณนาค (ที่ปรึกษาคณะอนุกรรมาธิการ).
# Chair unchanged: นางธารนี ปรีดาสันติ์. Non-senators are counted only, never named (members.py rule 1).
# Changes: transport/2569/index.html MEMBERS (isantransit group, list date) + SUBS member count + XSHARE version;
# transport/2569/share/members-isantransit.html (count 5 -> 8 and card version, page layers kept); new card picture and 1 official
# portrait (img/m/25691109_115149.jpg). Independent of items 199/200. Idempotent; no git, no network. Needs $HUB.
set -euo pipefail
: "${HUB:?HUB not set}"
rm -rf /tmp/205_transport_isantransit_members_payload
mkdir -p /tmp/205_transport_isantransit_members_payload
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 > /tmp/205_transport_isantransit_members_payload/p.b64
base64 -d /tmp/205_transport_isantransit_members_payload/p.b64 > /tmp/205_transport_isantransit_members_payload/p.tgz
echo "69995b28ef0fc256fe207b99a36728efe1980c8a37e82bcd8d1e89b7daa2cdc0  /tmp/205_transport_isantransit_members_payload/p.tgz" | sha256sum -c --quiet - || { echo "205_transport_isantransit_members: embedded payload damaged" >&2; exit 1; }
tar -xzf /tmp/205_transport_isantransit_members_payload/p.tgz -C /tmp/205_transport_isantransit_members_payload
test -f /tmp/205_transport_isantransit_members_payload/payload.json
python3 - "$HUB" /tmp/205_transport_isantransit_members_payload <<'PY'
import json, os, re, shutil, sys
HUB, SRC = sys.argv[1:3]
P = json.load(open(os.path.join(SRC, "payload.json"), encoding="utf-8"))
CMP = dict(ensure_ascii=False, separators=(",", ":"))
ser = lambda a: json.dumps(a, **CMP).replace("</", "<\\/")
NAME = "205_transport_isantransit_members"
changed = []

def put(path, text):
    if open(path, encoding="utf-8").read() != text:
        open(path, "w", encoding="utf-8").write(text); changed.append(os.path.relpath(path, HUB))

def jline(lines, prefix, page):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, f"{page}: {prefix} line not found once"
    i = idx[0]; line = lines[i]; body = line[len(prefix):]; tail = body[len(body.rstrip().rstrip(";")):]
    v = json.loads(body[:len(body) - len(tail)])
    assert prefix + ser(v) + tail == line, f"{page}: {prefix} does not round-trip; not touching it"
    return i, v, (lambda nv: prefix + ser(nv) + tail)

# 1. Transport home: MEMBERS (isantransit group + list date), SUBS member count, share-link version of the members card
page = "transport/2569/index.html"; p = os.path.join(HUB, page)
lines = open(p, encoding="utf-8").read().split("\n")
i, mem, mk = jline(lines, "const MEMBERS=", page)
gs = [g for g in mem["groups"] if g["key"] == "isantransit"]; assert len(gs) == 1, "MEMBERS: isantransit group missing"
g = gs[0]
for k, v in P["group"].items():
    assert k in g, f"MEMBERS isantransit: field {k} missing"
    g[k] = v
if mem["fetched"] < P["fetched"]:
    mem["fetched"] = P["fetched"]
lines[i] = mk(mem)
i, subs, mk = jline(lines, "const SUBS=", page)
ss = [s for s in subs if s["key"] == "isantransit"]; assert len(ss) == 1, "SUBS: isantransit missing"
ss[0]["members"] = P["sub_members"]
if ss[0].get("fetched", "") < P["sub_fetched"]:
    ss[0]["fetched"] = P["sub_fetched"]
lines[i] = mk(subs)
xs = [j for j, l in enumerate(lines) if "/*XSHARE*/" in l]; assert len(xs) == 1, "XSHARE line not found once"
old = f"share/members-isantransit.html?v={P['old_hash']}"; new = f"share/members-isantransit.html?v={P['new_hash']}"
assert lines[xs[0]].count(old) + lines[xs[0]].count(new) == 1, "XSHARE: members-isantransit entry not found once"
lines[xs[0]] = lines[xs[0]].replace(old, new)
put(p, "\n".join(lines))

# 2. the members share page: senator count and card version (the rest of the live page, e.g. its layers, stays)
rel = "transport/2569/share/members-isantransit.html"; p = os.path.join(HUB, rel); t = open(p, encoding="utf-8").read()
if P["new_count"] not in t:
    assert t.count(P["old_count"]) == P["new_count_n"], f"{rel}: senator count text not as expected"
    t = t.replace(P["old_count"], P["new_count"])
if f"members-isantransit-{P['new_hash']}.jpg" not in t:
    assert t.count(P["old_hash"]) == P["new_hash_n"], f"{rel}: card version not as expected"
    t = t.replace(P["old_hash"], P["new_hash"])
put(p, t)

# 3. new files: members card picture, official portrait of the senator who joined
for rel in P["files"]:
    s, d = os.path.join(SRC, rel), os.path.join(HUB, rel)
    os.makedirs(os.path.dirname(d), exist_ok=True)
    if not (os.path.exists(d) and open(s, "rb").read() == open(d, "rb").read()):
        shutil.copyfile(s, d); changed.append(rel)
print(f"{NAME}: changed", len(changed), "files:", ", ".join(changed) if changed else "none (already applied)")

# self-check
t = open(os.path.join(HUB, page), encoding="utf-8").read()
mem = json.loads([l for l in t.split("\n") if l.startswith("const MEMBERS=")][0][len("const MEMBERS="):].rstrip().rstrip(";"))
g = [g for g in mem["groups"] if g["key"] == "isantransit"][0]
assert all(g[k] == v for k, v in P["group"].items()), "MEMBERS isantransit not right"
assert all(os.path.exists(os.path.join(HUB, "transport/2569/" + x["i"])) for x in g["people"] + g["advisers"]), "portrait missing"
subs = json.loads([l for l in t.split("\n") if l.startswith("const SUBS=")][0][len("const SUBS="):].rstrip().rstrip(";"))
assert [s for s in subs if s["key"] == "isantransit"][0]["members"] == P["sub_members"], "SUBS count not right"
assert f"members-isantransit.html?v={P['new_hash']}" in t
sh = open(os.path.join(HUB, "transport/2569/share/members-isantransit.html"), encoding="utf-8").read()
assert sh.count(P["new_count"]) == P["new_count_n"] and sh.count(P["new_hash"]) == P["new_hash_n"] and P["old_count"] not in sh and P["old_hash"] not in sh, "share page not right"
assert os.path.exists(os.path.join(HUB, f"transport/2569/img/share/members-isantransit-{P['new_hash']}.jpg"))
print(f"{NAME} OK")
PY
rm -rf /tmp/205_transport_isantransit_members_payload
exit 0
